// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 t1, uint256 t2) public {
        t1 = bound(t1, 1, type(uint256).max / 2);
        t2 = bound(t2, 0, t1);
        uint256 before = c.pastBlockTime();

        vm.warp(t1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        vm.warp(t2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: after pastBlockTime has been set from a successful call,
        // no call at an equal-or-smaller timestamp may succeed; pastBlockTime
        // must never move backwards across successful calls.
        assertTrue(!ok2 && c.pastBlockTime() >= before);
    }
}
